/**
 * Compiled bundle fixture (never executed by the scanner).
 *
 * Mirrors a published `@deepseek-ai/dsh-client-ui-*` browser half: a
 * `const NS` namespace, a shared dictionary spread into `en`, and the
 * bilingual `ctx.locale.register(NS, { zh, en })` call.
 */
//#region lib/types/client/locales.js
const NS = "compiled.one";
const SHARED = {
	"shared.key": "Shared value",
	"deep.key": "Deep {n}"
};
const zh = {
	"greet": "你好 {name}",
	"alpha.only": "仅阿尔法",
	...SHARED
};
const en = {
	"greet": "Hello {name}",
	"alpha.only": "Alpha only",
	...SHARED
};
//#endregion
//#region lib/types/client/index.js
/** Comment must be ignored: ctx.locale.register("ghost.one", { en: { ghost: "Ghost" } }); */
function apply(ctx) {
	ctx.effect(() => ctx.locale.register(NS, {
		zh,
		en
	}), "ui-compiled-one: dictionaries");
}
export { apply };
//#endregion
